const $=id=>document.getElementById(id);
const CATEGORY={museum:'Science museum',nature_center:'Nature center',botanical_garden:'Botanical garden',observatory:'Planetarium / observatory',university:'University',research_center:'Research institute',zoo_aquarium:'Zoo / wildlife'};
const ICON={museum:'⚗',nature_center:'🌿',botanical_garden:'🌱',observatory:'✦',university:'▦',research_center:'⌬',zoo_aquarium:'🦉'};
const ACCESS_COLOR={public_venue:'#084B9E',scheduled_public:'#B68C3B',research_campus:'#9E382E'};
const PLACES=DATA.places.filter(p=>p.state==='TX').map(p=>({...p,lat:p.coordinates.lat,lng:p.coordinates.lng,dfw:p.region==='dfw'}));
let region='dfw',area='all',kind='all',access='all',selectedId=null;
const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const eligible=()=>{
 const q=$('search').value.trim().toLowerCase();
 return PLACES.filter(p=>(region==='tx'||p.dfw)&&(region==='dfw'||area==='all'||p.region===area)&&(kind==='all'||p.category===kind)&&(access==='all'||p.access.level===access)&&(!q||[p.name,p.city,p.summary,p.category,CATEGORY[p.category],p.access.label,...p.topics].join(' ').toLowerCase().includes(q)));
};
const map=L.map('geoMap',{zoomControl:false,minZoom:3,maxZoom:19});
const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{
 maxZoom:19,updateWhenIdle:true,referrerPolicy:'strict-origin-when-cross-origin',
 attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
});
const failedTiles=new Set();
function updateTileStatus(){ $('streetStatus').classList.toggle('hidden',failedTiles.size===0) }
tiles.on('tileerror',e=>{failedTiles.add(e.tile);updateTileStatus()});
tiles.on('tileunload tileload',e=>{if(failedTiles.delete(e.tile))updateTileStatus()});
$('retryMap').onclick=()=>tiles.redraw();
tiles.addTo(map);
const clusters=L.markerClusterGroup({
 maxClusterRadius:36,showCoverageOnHover:false,
 iconCreateFunction:group=>{
  const count=group.getChildCount();
  return L.divIcon({className:'atlas-cluster',html:'<span aria-label="'+count+' nearby places">'+count+'</span>',iconSize:[34,34]});
 }
}).addTo(map);
const selection=L.layerGroup().addTo(map);
function renderPins(){
 clusters.clearLayers();selection.clearLayers();
 const markers=[];
 for(const p of eligible()){
  const selected=p.id===selectedId;
  const icon=L.divIcon({className:'atlas-pin'+(selected?' selected':''),
   html:'<span style="--pin-color:'+ACCESS_COLOR[p.access.level]+'"></span>',iconSize:[30,30]});
  const marker=L.marker([p.lat,p.lng],{icon,title:p.name,alt:p.name,zIndexOffset:selected?1000:0});
  marker.on('click',()=>selectPlace(p.id,false));
  if(selected){
   const label=document.createElement('span');label.textContent=p.name;
   marker.bindTooltip(label,{permanent:true,direction:'top',offset:[0,-10]});
   selection.addLayer(marker);
  }else markers.push(marker);
 }
 clusters.addLayers(markers);
}
function resetView(){
 const bounds=region==='tx'&&area==='all'?[[25.84,-106.65],[36.50,-93.50]]:
  PLACES.filter(p=>region==='dfw'?p.dfw:p.region===area).map(p=>[p.lat,p.lng]);
 map.fitBounds(bounds,{padding:[24,40],maxZoom:12,animate:false});
}
function renderList(){const list=eligible();$('resultCount').textContent=`${list.length} location${list.length!==1?'s':''} · ${region==='dfw'?'Dallas–Fort Worth focus':area==='all'?'statewide listings':$('area').selectedOptions[0].textContent}`;const root=$('placeList');root.replaceChildren();if(!list.length){root.innerHTML='<p class="no-results">No entries match those filters. Try another category or search.</p>';return}
 list.forEach(p=>{const b=document.createElement('button');b.type='button';b.className='place'+(p.id===selectedId?' selected':'');b.innerHTML=`<span class="marker-icon" aria-hidden="true">${ICON[p.category]}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.city)} · ${esc(CATEGORY[p.category])}</small><em>${esc(p.access.label)}</em></span>`;b.addEventListener('click',()=>selectPlace(p.id,true));root.appendChild(b)});
}
function renderProfile(){const p=PLACES.find(p=>p.id===selectedId);const pane=$('profile');if(!p){const count=eligible().length;pane.innerHTML=`<div class="sec-label">Explore the directory</div><h2>Science happens nearby.</h2><div class="hero-stat">${count}</div><p class="hero-caption">places in your current selection</p><p>Select a marker or listing to see what an institution does and how the public can engage with it.</p><div class="card"><strong>Public access and research are different</strong><p>Museums and gardens generally welcome visitors, sometimes with admission. Research campuses and labs are listed for discovery, but require permission for visits.</p></div><div class="section-name">About this pilot</div><p>This statewide discovery collection is growing from Dallas–Fort Worth. It does not claim complete coverage or verified visiting conditions. Filter by region to browse more easily.</p>`;return}
 const bg={'museum':'#EDF5FB','nature_center':'#EFF7EF','botanical_garden':'#EFF7EF','observatory':'#FBF4E4','university':'#FAEFED','research_center':'#FAEFED','zoo_aquarium':'#EFF7EF'}[p.category];
 const fg=ACCESS_COLOR[p.access.level];
 const checked=p.review.status==='verified';const advisory=p.access.advisory==='temporarily_closed'?`<div class="review" style="margin-top:11px;background:#FCEDEA;color:#94372A;border-color:#EEC9C0"><strong>Temporarily closed</strong> · Information checked ${esc(p.access.advisory_as_of||'date unknown')}. Follow the official site for reopening updates.</div>`:'';
 pane.innerHTML=`<div class="sec-label">Location profile</div><span class="pill" style="background:${bg};color:${fg}">${esc(CATEGORY[p.category])}</span><h2>${esc(p.name)}</h2><p>${esc(p.address)}</p>${advisory}<div class="section-name">What you'll find</div><p>${esc(p.summary)}</p><div class="section-name">Science topics</div><div class="tagset">${p.topics.map(t=>`<span class="topic">${esc(t)}</span>`).join('')}</div><div class="section-name">Visitor access</div><div class="access"><strong>${esc(p.access.label)}</strong><p>${esc(p.access.notes)}</p></div><div class="section-name">Editorial check</div><div class="review">${checked?'✓ Reviewed listing':'Source review pending — preliminary profile'}</div><p class="note">Pins show approximate locations, not verified entrances. Confirm public access, admission and directions on the official website.</p><div class="section-name">Institution references</div><a class="link" href="${esc(p.links.official_url)}" target="_blank" rel="noopener noreferrer">Official website ↗</a>${p.review.sources.slice(0,3).map(s=>`<a class="link" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.purpose)} ↗</a>`).join('')}`;


 // Street geometry is real, but preliminary institution pins are approximate.
 // Search by name and address rather than treating the pin as a verified entrance.
 const streetActions=document.createElement('div');
 streetActions.className='card';
 const maps=document.createElement('a');
 maps.className='link';maps.target='_blank';maps.rel='noopener noreferrer';
 maps.href='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(p.name+', '+p.address);
 maps.textContent='Find address and directions in Maps ↗';
 streetActions.appendChild(maps);
 const caution=document.createElement('p');
 caution.className='note';
 caution.textContent='The Atlas pin is approximate. Use the organizer’s official directions to find the correct visitor entrance.';
 streetActions.appendChild(caution);
 pane.appendChild(streetActions);

 // Show dated opportunities on the institution profile without changing access policy.
 const upcoming=EVENTS.filter(e=>e.institution_id===p.id&&new Date(e.start_at).getTime()>=Date.now()).sort((a,b)=>a.start_at.localeCompare(b.start_at)).slice(0,3);
 if(upcoming.length){
  const section=document.createElement('div');section.className='card';
  section.innerHTML=`<strong>Upcoming science events (${upcoming.length})</strong><p>${upcoming.map(e=>esc(e.start_at.slice(0,10)+' · '+e.title)).join('<br>')}</p><button id="seeVenueEvents" type="button" style="margin-top:12px;padding:9px 10px;border-radius:7px;background:#084B9E;color:white;border:0;font-size:12px;font-weight:750">View in events calendar</button><p class="note">Source-checked, pending editorial approval. Restrictions apply.</p>`;
  pane.appendChild(section);
  section.querySelector('#seeVenueEvents').onclick=()=>{initCalendar();const first=upcoming[0];calYear=+first.start_at.slice(0,4);calMonth=+first.start_at.slice(5,7)-1;calSelected=null;$('eventRegion').value='all';$('eventType').value='all';$('eventAccess').value='all';$('eventSearch').value=p.name;showTab('calendar');};
 }
}
function selectPlace(id,recenter){const p=PLACES.find(p=>p.id===id);if(!p)return;selectedId=id;renderList();renderProfile();if(recenter)map.setView([p.lat,p.lng],Math.max(map.getZoom(),15),{animate:false});renderPins();if(recenter&&matchMedia('(max-width:630px)').matches)$('geoMap').scrollIntoView({block:'center'});const selected=$('placeList').querySelector('.selected');if(selected&&!recenter){const list=$('placeList');list.scrollTop+=selected.getBoundingClientRect().top-list.getBoundingClientRect().top;}}
function chooseRegion(next){region=next;area='all';$('area').value='all';$('crumbRegion').textContent=next==='dfw'?'Dallas–Fort Worth focus':'All Texas';selectedId=null;$('dfwButton').classList.toggle('active',next==='dfw');$('texasButton').classList.toggle('active',next==='tx');$('dfwButton').setAttribute('aria-pressed',String(next==='dfw'));$('texasButton').setAttribute('aria-pressed',String(next==='tx'));$('directoryTitle').textContent=next==='dfw'?'North Texas':'Texas directory';$('directorySubtitle').textContent=next==='dfw'?'Explore the Dallas–Fort Worth science community.':'Browse science locations across Texas by region.';$('mapTitle').textContent=next==='dfw'?'Dallas–Fort Worth, Texas':'Texas · Statewide';resetView();renderPins();renderList();renderProfile()}
$('zoomIn').onclick=()=>map.zoomIn();
$('zoomOut').onclick=()=>map.zoomOut();
$('resetMap').onclick=resetView;
$('dfwButton').onclick=()=>chooseRegion('dfw');$('texasButton').onclick=()=>chooseRegion('tx');
$('area').onchange=e=>{const next=e.target.value;if(region!=='tx')chooseRegion('tx');area=next;$('area').value=next;$('crumbRegion').textContent=next==='all'?'All Texas':$('area').selectedOptions[0].textContent;selectedId=null;resetView();renderPins();renderList();renderProfile();};
$('kind').onchange=e=>{kind=e.target.value;selectedId=null;renderList();renderPins();renderProfile()};
$('access').onchange=e=>{access=e.target.value;selectedId=null;renderList();renderPins();renderProfile()};
$('search').oninput=()=>{selectedId=null;renderList();renderPins();renderProfile()};

// Calendar view uses a separate event dataset keyed to existing institution IDs.
let calYear,calMonth,monthFormat,dateFormat,clockFormat,calSelected=null;
function initCalendar(){
 if(monthFormat)return;
 const localNowParts=new Intl.DateTimeFormat('en-US',{year:'numeric',month:'numeric',timeZone:'America/Chicago'}).formatToParts(new Date());
 calYear=+localNowParts.find(p=>p.type==='year').value,calMonth=+localNowParts.find(p=>p.type==='month').value-1;
 monthFormat=new Intl.DateTimeFormat('en-US',{month:'long',year:'numeric',timeZone:'America/Chicago'});
 dateFormat=new Intl.DateTimeFormat('en-US',{weekday:'short',month:'short',day:'numeric',timeZone:'America/Chicago'});
 clockFormat=new Intl.DateTimeFormat('en-US',{hour:'numeric',minute:'2-digit',timeZone:'America/Chicago'});
}
const eventDay=e=>e.start_at.slice(0,10);
const regionForEvent=e=>PLACES.find(p=>p.id===e.institution_id)?.region||'unknown';
const institutionFor=e=>PLACES.find(p=>p.id===e.institution_id);
const eventLabel={nature:'Nature & ecology',environment:'Conservation',workshop:'Workshop',science_social:'Science social',creative_science:'Creative & science',family:'Family activity',astronomy:'Astronomy',lecture:'Lecture',camp:'Camp',other:'Event'};
function showTab(tab){const isMap=tab==='map';$('atlasMapView').classList.toggle('hidden',!isMap);$('calendarView').classList.toggle('hidden',isMap);$('mapTab').classList.toggle('active',isMap);$('calendarTab').classList.toggle('active',!isMap);$('mapTab').setAttribute('aria-pressed',String(isMap));$('calendarTab').setAttribute('aria-pressed',String(!isMap));if(isMap)map.invalidateSize();else{initCalendar();renderCalendar()}}
function filteredEvents(){
 const region=$('eventRegion').value,kind=$('eventType').value,access=$('eventAccess').value,q=$('eventSearch').value.trim().toLowerCase();
 return EVENTS.filter(e=>{
  const org=institutionFor(e);
  const accessMatch=access==='all'||(access==='public'&&e.access!=='restricted')||(access==='restricted'&&e.access==='restricted');
  return org&&(region==='all'||org.region===region)&&(kind==='all'||e.category===kind)&&accessMatch&&(!q||[e.title,e.summary,e.audience,org.name,org.city].join(' ').toLowerCase().includes(q));
 }).sort((a,b)=>a.start_at.localeCompare(b.start_at));
}
function changeMonth(d){calMonth+=d;if(calMonth<0){calMonth=11;calYear--;}if(calMonth>11){calMonth=0;calYear++;}calSelected=null;renderCalendar();}
function dateKey(year,month,day){return `${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;}
function renderCalendar(){const list=filteredEvents();const monthStart=dateKey(calYear,calMonth,1).slice(0,7);$('calendarHeading').textContent=monthFormat.format(new Date(Date.UTC(calYear,calMonth,10,12)));
 const days=new Date(Date.UTC(calYear,calMonth+1,0)).getUTCDate(),start=new Date(Date.UTC(calYear,calMonth,1)).getUTCDay();const grid=$('calendarGrid');grid.replaceChildren();
 for(let i=0;i<start;i++){const blank=document.createElement('div');blank.className='cal-day empty';blank.setAttribute('aria-hidden','true');grid.appendChild(blank)}
 for(let day=1;day<=days;day++){const d=dateKey(calYear,calMonth,day),hits=list.filter(e=>eventDay(e)===d),btn=document.createElement('button');btn.type='button';btn.className='cal-day'+(calSelected===d?' active':'');btn.setAttribute('aria-label',`${d}, ${hits.length} event${hits.length===1?'':'s'}`);btn.setAttribute('aria-pressed',String(calSelected===d));const t=document.createElement('time');t.dateTime=d;t.textContent=day;btn.append(t);if(hits.length){const b=document.createElement('span');b.className='count'+(hits.every(e=>e.access==='restricted')?' restricted':'');b.textContent=hits.length===1?'1 event':`${hits.length} events`;btn.append(b)}btn.onclick=()=>{calSelected=calSelected===d?null:d;renderCalendar()};grid.append(btn)}
 const shown=list.filter(e=>eventDay(e).startsWith(monthStart)&&(!calSelected||eventDay(e)===calSelected));$('eventListTitle').textContent=calSelected?dateFormat.format(new Date(calSelected+'T12:00:00-06:00')):'Events this month';$('eventCount').textContent=`${shown.length} event${shown.length===1?'':'s'} · ${calSelected?'Selected date':'Current filters'}`;
 const root=$('eventCards');root.replaceChildren();if(!shown.length){root.innerHTML='<div class="no-events">No events match this month and the selected filters. Try another month or include restricted-access programs. Calendar coverage is expanding; entries require rechecking before attending. Not yet a live aggregation feed.</div>';return}
 shown.forEach(e=>{const org=institutionFor(e),card=document.createElement('article');card.className='event-card';const startTime=new Date(e.start_at),endTime=e.end_at?new Date(e.end_at):null,sameDay=!endTime||e.start_at.slice(0,10)===e.end_at.slice(0,10);const when=`${dateFormat.format(startTime)} · ${clockFormat.format(startTime)}`+(endTime?(sameDay?`–${clockFormat.format(endTime)}`:`–${dateFormat.format(endTime)} ${clockFormat.format(endTime)}`):' · end time not listed');const status=e.access==='restricted'?'Restricted / institution-affiliated':e.access==='registration'?'Registration may be required':'Public program';card.innerHTML=`<h4>${esc(e.title)}</h4><div class="meta">${esc(when)} · CT</div><div class="meta">${esc(e.delivery==='online'?'Online session · '+org.name:org.name+' · '+org.city)}</div><div class="event-tags"><span class="event-tag">${esc(eventLabel[e.category])}</span><span class="event-tag ${e.access==='restricted'?'restricted':''}">${esc(status)}</span></div><p class="event-desc">${esc(e.summary)}</p>${e.availability_note?`<p class="event-desc"><strong>Tickets:</strong> ${esc(e.availability_note)}</p>`:""}<div class="meta">For: ${esc(e.audience)} · Official source checked ${esc(e.source_checked_at)}</div><div class="event-links"><a href="${esc(e.source_url)}" target="_blank" rel="noopener noreferrer">Official event information ↗</a><button type="button">Add to calendar (.ics)</button></div>`;card.querySelector('button').onclick=()=>saveIcs(e);root.appendChild(card)})
}
function icsEscape(s){return String(s).replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;')}
function saveIcs(e){const start=new Date(e.start_at).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z');const end=e.end_at?new Date(e.end_at).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z'):null;const org=institutionFor(e);const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Frameworked//Science Atlas//EN','BEGIN:VEVENT',`UID:${e.id}@frameworked.org`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z')}`,`DTSTART:${start}`,...(end?[`DTEND:${end}`]:[]),`SUMMARY:${icsEscape(e.title)}`,`LOCATION:${icsEscape(e.delivery==='online'?'Online — see organizer link':org.name+', '+org.city+', Texas')}`,`DESCRIPTION:${icsEscape(e.summary+' — Verify schedule and access on the organizer site: '+e.source_url)}`,`URL:${e.source_url}`,'END:VEVENT','END:VCALENDAR'];const blob=new Blob([lines.join('\r\n')+'\r\n'],{type:'text/calendar;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=e.id+'.ics';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('mapTab').onclick=()=>showTab('map');$('calendarTab').onclick=()=>showTab('calendar');$('prevMonth').onclick=()=>changeMonth(-1);$('nextMonth').onclick=()=>changeMonth(1);$('todayMonth').onclick=()=>{const now=new Date(),parts=new Intl.DateTimeFormat('en-US',{year:'numeric',month:'numeric',timeZone:'America/Chicago'}).formatToParts(now);calYear=+parts.find(p=>p.type==='year').value;calMonth=+parts.find(p=>p.type==='month').value-1;calSelected=null;renderCalendar()};
['eventRegion','eventType','eventAccess'].forEach(id=>$(id).onchange=()=>{calSelected=null;renderCalendar()});$('eventSearch').oninput=()=>{calSelected=null;renderCalendar()};

chooseRegion('dfw');
